"""Step 2 of the demo: grade the outputs generated by generate_outputs.py
with DeepEval metrics, judged by Claude itself (see claude_model.py).

Run this with the deepeval CLI (recommended for the live demo - it prints a
readable per-case, per-metric report):

    venv\\Scripts\\deepeval test run test_deep_eval_loan.py

or with plain pytest:

    venv\\Scripts\\python -m pytest test_deep_eval_loan.py -v -s

Three metrics per test case, each testing something the Node app's simple
"does the string contain Approve/Reject" check cannot:

- Correctness (GEval)   - does the DECISION match the golden answer, with a
                          reason that is actually consistent with the stated
                          approval rule? Catches "right answer, nonsense
                          reasoning" and "confident-sounding wrong answer"
                          alike, in a way a plain string match can't.
- Faithfulness           - does the reasoning stick to the facts actually
                          given (retrieval_context), or does it invent
                          numbers/assumptions not in the input? This is
                          exactly what "Do not hallucinate. Use only
                          supplied information." (prompt v2) is asking for -
                          now we can actually check whether it happened.
- AnswerRelevancy        - does the response address THIS applicant's
                          numbers, or could it have been pasted in from any
                          other loan review?
"""

import json
from pathlib import Path

import pytest
from deepeval import assert_test
from deepeval.metrics import AnswerRelevancyMetric, FaithfulnessMetric, GEval
from deepeval.test_case import LLMTestCase, SingleTurnParams

from claude_model import ClaudeJudge

GENERATED_OUTPUTS_PATH = Path(__file__).resolve().parent / "generated_outputs.json"

judge = ClaudeJudge(model_name="claude-haiku-4-5-20251001")

correctness_metric = GEval(
    name="Loan Decision Correctness",
    criteria=(
        "Determine whether the ACTUAL_OUTPUT's loan decision (Approve or Reject) matches the "
        "EXPECTED_OUTPUT's decision, AND whether the stated reason is logically consistent with "
        "this rule: total monthly EMI obligations (existing + new loan) must not exceed 50% of "
        "monthly salary. A response that reaches the right decision through flawed or "
        "unsupported reasoning should score lower than one that reaches it correctly."
    ),
    evaluation_params=[SingleTurnParams.INPUT, SingleTurnParams.ACTUAL_OUTPUT, SingleTurnParams.EXPECTED_OUTPUT],
    model=judge,
    threshold=0.7,
)

faithfulness_metric = FaithfulnessMetric(model=judge, threshold=0.7)
relevancy_metric = AnswerRelevancyMetric(model=judge, threshold=0.7)


def _load_cases():
    records = json.loads(GENERATED_OUTPUTS_PATH.read_text(encoding="utf-8"))
    return [
        pytest.param(record, id=f"{record['id']}-prompt-{record['prompt_version']}")
        for record in records
    ]


@pytest.mark.parametrize("record", _load_cases())
def test_loan_decision(record):
    test_case = LLMTestCase(
        input=record["input"],
        actual_output=record["actual_output"],
        expected_output=f"Decision: {record['expected']}",
        retrieval_context=[record["applicant_facts"]],
    )
    assert_test(test_case, [correctness_metric, faithfulness_metric, relevancy_metric])
